function updateTrialSummary(){const ai=history.filter(s=>s.declaredTester==='ai'),humans=history.filter(s=>s.declaredTester==='self-declared human');if(ai.length||humans.length)$('#external-proof').textContent=`This tab: ${humans.length} self-declared human run(s), ${humans.filter(x=>x.completed).length} completed; ${ai.length} labeled AI run(s), ${ai.filter(x=>x.completed).length} completed. Labels are self-reported. These runs do not establish an independent human-vs-AI success rate.`}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadTicket(){const seconds=session.durationSeconds;const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="420" viewBox="0 0 900 420"><rect width="900" height="420" rx="22" fill="#090b14"/><rect x="18" y="18" width="864" height="384" rx="14" fill="none" stroke="#9ab1d5" stroke-width="3"/><path d="M650 18V402" stroke="#9ab1d5" stroke-width="2" stroke-dasharray="8 8"/><text x="55" y="80" font-family="sans-serif" font-weight="bold" font-size="28" fill="#9ab1d5">meatspace ✳</text><text x="55" y="125" font-family="monospace" font-size="12" fill="#6986ad">DISTRICT 404 // HUMAN AFTER HOURS</text><text x="55" y="215" font-family="sans-serif" font-weight="900" font-size="65" fill="#d2fe60">ADMIT ONE.</text><text x="55" y="265" font-family="sans-serif" font-size="26" fill="#9ab1d5">OFFLINE SOUL. ONLINE CHAOS.</text><text x="55" y="340" font-family="monospace" font-size="13" fill="#6986ad">${seconds}s / 3 HANDSHAKES / ZERO PERSONAL DATA</text><text x="55" y="370" font-family="monospace" font-size="10" fill="#6986ad">DEMO PASS — NOT A SECURITY CREDENTIAL</text><circle cx="760" cy="176" r="62" fill="#ff49bd" stroke="#9ab1d5" stroke-width="2"/><ellipse cx="741" cy="166" rx="5" ry="10" fill="#9ab1d5"/><ellipse cx="779" cy="166" rx="5" ry="10" fill="#9ab1d5"/><path d="M739 194q20 24 44-3" fill="none" stroke="#9ab1d5" stroke-width="3"/><text x="710" y="297" font-family="monospace" font-size="13" fill="#9ab1d5">GUEST #${String(guest).padStart(3,'0')}</text><text x="706" y="326" font-family="monospace" font-size="10" fill="#6986ad">REAL-CODED. AURA MAXED.</text></svg>`;download(new Blob([svg],{type:'image/svg+xml'}),'meatspace-admit-one.svg');toast('Pass downloaded. Valid nowhere. Emotionally priceless.')}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<35;i++){const c=document.createElement('i');c.className='confetti';c.style.left=rand(0,100)+'vw';c.style.background=['#d2fe60','#bd94ff','#ff49bd','#49e7ec'][i%4];c.style.animationDelay=rand(0,.6)+'s';document.body.append(c);setTimeout(()=>c.remove(),3300)}}
$('#restart').onclick=newGuest;$('#relaxed').setAttribute('aria-pressed',String(relaxed));$('#relaxed').onclick=()=>{relaxed=!relaxed;$('#relaxed').setAttribute('aria-pressed',String(relaxed));if(session)session.relaxedTiming=relaxed;if(stage===2||stage===3)render();toast(relaxed?'CHILL MODE ON. Wider signal. Longer fist-bump window.':'LOCK-IN MODE ON. Same quests, a little snappier.')};
$('#hint').onclick=()=>openModal('CHEAT CODE ACQUIRED.',['Start the handshake when you’re ready. Three small interactions, unlimited retries. Relaxed timing gives you more room. No accounts, microphones, cameras, or personal questions.','Pick the most ordinary, familiar response. This is the warm-up, not a claim that AI can’t understand everyday life.','Press Start neon drift. Move your mouse or finger horizontally inside the scene so the disco ball stays inside the spotlight. Or use the slider with arrow keys. Fill the little bar. Relaxed timing widens the light.','Press Ready. Wait for the hand to actually appear, then tap it or press Space while the scene or button has focus. Use Relaxed timing for a longer window. Unlimited retries.','You’re in. Download your pass, or start another guest. It’s a demo result, not a security token.'][stage]);
$('#about').onclick=()=>openModal('DISTRICT 404 // THE LORE.','MEATSPACE swaps traffic-light grids for a 20-second social handshake: everyday intuition, live visuomotor tracking, and a reactive high five. Language models can answer the warm-up. The experiment is whether slower screenshot-and-click agents miss the live moments. The bot bench shows real deterministic checks, not a fake AI leaderboard. Independent human and AI trials still matter.');
$('#privacy').onclick=()=>openModal('Zero personal data. Zero secret cameras.','The app asks for no account, name, email, camera, microphone, or biometrics. No analytics, fingerprinting, cookies, local storage, or tracking requests. Temporary game state and aggregate pass/fail evidence exist only in this tab; raw pointer paths are not stored. Downloads happen only when you request them. Hosting and its sign-in gate are provided by Sites and may maintain their own normal access logs.');
$('#run-probes').onclick=()=>{probeResults=runBaselines();evidence.baselines=probeResults;$$('#probe-list>div').forEach((row,i)=>{const r=probeResults[i],em=row.querySelector('em');em.textContent=r.accepted?'ADMITTED':'BLOCKED';em.className=r.accepted?'passed':'blocked'});toast('Three baseline strategies blocked. Positive control admitted. These are local checks—not independent AI trials.')};
$('#download-report').onclick=()=>{updateTrialSummary();const report={...evidence,sessions:history,counts:{selfDeclaredHumanRuns:history.filter(x=>x.declaredTester==='self-declared human').length,labeledAiRuns:history.filter(x=>x.declaredTester==='ai').length,authorQaRuns:history.filter(x=>x.declaredTester==='author-qa').length},limitations:['Self-declared roles are not identity proof.','Baselines are deterministic local probes, not AI model evaluations.','Client-side checks are bypassable by source-aware or instrumented adversaries.','A controlled human trial and an independent AI trial have not been established by the author.']};download(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),'meatspace-session-evidence.json');toast('Evidence downloaded. No invented wins. No mysterious percentages.')};
$('#modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});

// Cosmetic interactions never alter CAPTCHA acceptance or collect player data.
let signal='acid',reactor=0,roastIndex=0;
const signals={acid:{color:'#d2fe60',rgb:'210,254,96',name:'CHAOS.KID',face:'⌐■_■'},pink:{color:'#ff49bd',rgb:'255,73,189',name:'GHOST.EXE',face:'✧_✧'},cyan:{color:'#49e7ec',rgb:'73,231,236',name:'SIDE.QUEST',face:'◕‿◕'}};
function updateXP(){const xp=stamps*400;$('#xp').textContent=String(xp).padStart(4,'0')+' / 1200';$('#xp-fill').style.width=(xp/1200*100)+'%';$('#rank-label').textContent=['RANK: UNVERIFIED LEGEND','RANK: REAL-CODED','RANK: AURA ACCUMULATOR','RANK: CERTIFIED MEATSPACE'][stamps]}
function xpBurst(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=$('#stage').getBoundingClientRect();const pop=document.createElement('span');pop.className='xp-pop';pop.textContent='+400 AURA';pop.style.left=Math.max(15,Math.min(window.innerWidth-150,r.right-150))+'px';pop.style.top=Math.max(65,r.top+50)+'px';document.body.append(pop);setTimeout(()=>pop.remove(),1300)}
$$('[data-signal]').forEach(b=>b.onclick=()=>{signal=b.dataset.signal;const chosen=signals[signal];document.documentElement.style.setProperty('--accent',chosen.color);document.documentElement.style.setProperty('--accent-rgb',chosen.rgb);$$('[data-signal]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#signal-lock').textContent=chosen.name+' CONNECTED';$('.bouncer-eyes').textContent=chosen.face;$('.player-console').classList.remove('signal-pulse');void $('.player-console').offsetWidth;$('.player-console').classList.add('signal-pulse');tone(440,.13,.025);toast(chosen.name+' connected. Cosmetic aura only. Same fair door test.')});
$('#orb').onclick=()=>{reactor=Math.min(100,reactor+20);$('#reactor-fill').style.width=reactor+'%';$('#reactor-label').textContent=reactor===100?'REACTOR // FULLY UNHINGED':`REACTOR // ${reactor}% CHARGED`;const shock=document.createElement('i');shock.className='reactor-shockwave';$('.cyber-scene').append(shock);setTimeout(()=>shock.remove(),750);tone(110+reactor*3,.3,.045,'sawtooth');if(reactor===100){$('.cyber-scene').classList.add('charged');$('#orb').setAttribute('aria-label','Reactor fully charged. Click to pulse the neon.');$('#orb small').innerHTML='STAY<br>UNHINGED';if(!$('#orb').dataset.charged){$('#orb').dataset.charged='true';toast('REACTOR ONLINE. The club is lit. Your humanity remains unverified.');chime()}}};
function dmSay(text,user=false){const p=document.createElement('p');p.textContent=text;if(user)p.className='user-message';$('#dm-messages').append(p);while($('#dm-messages').children.length>8)$('#dm-messages').firstElementChild.remove();$('#dm-messages').scrollTop=$('#dm-messages').scrollHeight}
$('#bouncer-dm').onclick=()=>{$('#dm-panel').classList.toggle('hidden');if(!$('#dm-panel').classList.contains('hidden'))$('#dm-close').focus()};$('#dm-close').onclick=()=>{$('#dm-panel').classList.add('hidden');$('#bouncer-dm').focus()};
$$('[data-dm]').forEach(b=>b.onclick=()=>{dmSay(b.textContent,true);if(b.dataset.dm==='help'){const tips=['hit “boot up my humanity.” three quests. unlimited retries. no need to be a speedrunner.','pick the most regular human answer. the warm-up is not where bots get humbled.','start neon drift. move your mouse, finger, or the slider so the orb stays inside the light. chill mode makes it wider.','press ready. WAIT for the hand. then tap it or press Space. chill mode gives you 2.4 seconds. you got this.','you’re literally in. grab your pass. go be someone’s plot twist.'];dmSay(tips[stage])}else if(b.dataset.dm==='roast'){const lines=['your aura has 47 browser tabs open and one is playing music.','you give “I’ll sleep early tonight” at 2:43 a.m. energy.','your screen-time report just requested emotional support.','you’re not a bot. a bot would have remembered why it opened the fridge.','you are the side quest. respectfully.'];dmSay(lines[roastIndex++%lines.length])}else dmSay('district 404. the bots took the guest list. we built a door test out of everyday cringe, a live neon signal, and a fist bump. no face scans. no data mining. just show up in the moment.')});
updateXP();

render();
